package tmmodern;
import java.util.List;import net.minecraft.core.*;import net.minecraft.resources.ResourceLocation;import net.minecraft.world.*;import net.minecraft.world.entity.*;import net.minecraft.world.entity.player.Player;import net.minecraft.world.item.*;import net.minecraft.world.item.context.UseOnContext;import net.minecraft.world.level.Level;import net.minecraft.world.effect.*;import net.minecraft.network.chat.Component;
public class UtilityItem extends Item implements thaumcraft.api.IWarpingGear {
    public final String kind;
    public UtilityItem(String kind){super(properties(kind));this.kind=kind;}
    static Properties properties(String kind){var p=new Properties().rarity(Rarity.RARE);if(kind.equals("gate_key")||kind.equals("flyte_charm"))p.stacksTo(1);if(kind.equals("magic_funguar")||kind.equals("nightshade_berries"))p.food(new net.minecraft.world.food.FoodProperties.Builder().nutrition(kind.equals("magic_funguar")?3:0).saturationMod(.2f).alwaysEat().build());return p;}
    @Override public boolean onEntityItemUpdate(ItemStack s,net.minecraft.world.entity.item.ItemEntity e){if(kind.startsWith("salis_"))TMRuntime.saltTick(e,this);return false;}
    @Override public int getWarp(ItemStack s,Player p){return kind.equals("gate_key")?3:kind.equals("flyte_charm")?5:0;}
    @Override public boolean hasCraftingRemainingItem(ItemStack s){return kind.endsWith("blood");}
    @Override public ItemStack getCraftingRemainingItem(ItemStack s){return new ItemStack(TMRuntime.item("thaumcraft:phial"));}
    @Override public ItemStack finishUsingItem(ItemStack stack,Level level,LivingEntity entity){
        if(kind.equals("gate_key")){if(entity instanceof net.minecraft.server.level.ServerPlayer p&&stack.hasTag()){var t=stack.getTag();var pos=new BlockPos(t.getInt("posX"),t.getInt("posY"),t.getInt("posZ"));String fail=!p.level().dimension().location().toString().equals(t.getString("dimension"))?"key.invaliddim":!level.isEmptyBlock(pos)||!level.isEmptyBlock(pos.above())?"key.error":null;if(fail==null){p.teleportTo(pos.getX()+.5,pos.getY(),pos.getZ()+.5);p.addEffect(new MobEffectInstance(MobEffects.CONFUSION,160));TMRuntime.sound(level,pos,"minecraft:entity.enderman.teleport",5,1);}else p.displayClientMessage(Component.translatable(fail),true);}return stack;}
        if(!level.isClientSide){if(kind.equals("magic_funguar")){entity.addEffect(new MobEffectInstance(MobEffects.REGENERATION,60,1));entity.addEffect(new MobEffectInstance(MobEffects.MOVEMENT_SPEED,100,2));if(entity instanceof net.minecraft.server.level.ServerPlayer p)tc4revival.research.KnowledgeSavedData.get(p.server).update(p.getUUID(),p.getRandom()::nextInt,k->{k.changePool(MagicFocus.aspect(List.of("aer","terra","ignis","aqua","ordo","perditio").get(p.getRandom().nextInt(6))),(short)1);return null;});}else if(kind.equals("nightshade_berries"))entity.hurt(TMRuntime.nightshade(level),Short.MAX_VALUE);}
        return super.finishUsingItem(stack,level,entity);}
    @Override public UseAnim getUseAnimation(ItemStack s){return kind.equals("gate_key")?UseAnim.BOW:super.getUseAnimation(s);}
    @Override public int getUseDuration(ItemStack s){return kind.equals("gate_key")?40:super.getUseDuration(s);}
    @Override public InteractionResultHolder<ItemStack> use(Level l,Player p,InteractionHand hand){var s=p.getItemInHand(hand);if(kind.equals("gate_key")){if(s.hasTag()&&s.getTag().contains("dimension")){p.startUsingItem(hand);return InteractionResultHolder.consume(s);}return InteractionResultHolder.pass(s);}return super.use(l,p,hand);}
    @Override public InteractionResult useOn(UseOnContext c){var p=c.getPlayer();if(p==null)return InteractionResult.PASS;var level=c.getLevel();var pos=c.getClickedPos();var stack=c.getItemInHand();if(!level.mayInteract(p,pos))return InteractionResult.FAIL;
        if(kind.equals("gate_key")){if(!stack.getOrCreateTag().contains("dimension")&&!level.isClientSide){var t=stack.getOrCreateTag();t.putString("dimension",level.dimension().location().toString());t.putInt("posX",pos.getX());t.putInt("posY",pos.getY()+1);t.putInt("posZ",pos.getZ());t.putInt("colour",1+level.random.nextInt(360));TMEffects.sparkles(level,net.minecraft.world.phys.Vec3.atCenterOf(pos),9,6,1.75f,.1f);TMRuntime.sound(level,pos,"thaumcraft:wand",1,1);}return InteractionResult.SUCCESS;}
        if(kind.equals("warp_fertilizer")&&level.getBlockState(pos).is(TMRuntime.block("thaumcraft:silverwood_sapling"))){if(!level.isClientSide){level.setBlock(pos,TaintedMagic.block("warpwood_sapling").defaultBlockState(),3);if(!p.isCreative())stack.shrink(1);TMEffects.sparkles(level,net.minecraft.world.phys.Vec3.atCenterOf(pos),15,0,1,.05f);TMRuntime.sound(level,pos,"thaumcraft:roots",1,1);}return InteractionResult.SUCCESS;}return InteractionResult.PASS;}
    @Override public void onUseTick(Level level,LivingEntity e,ItemStack stack,int remaining){if(kind.equals("gate_key")){if(level.isClientSide)TMEffects.localSparkles(level,e.position(),1,6,1.75f,.1f);else if(e.tickCount%5==0)TMRuntime.sound(level,e.blockPosition(),"thaumcraft:wind",.1f,1);}}
    @Override public void appendHoverText(ItemStack s,Level l,List<Component> lines,TooltipFlag f){if(kind.equals("gate_key")){var t=s.getTag();lines.add(Component.translatable(t!=null&&t.contains("dimension")?"key.bound":"key.unbound"));if(t!=null&&t.contains("dimension")){lines.add(Component.literal(t.getString("dimension")));lines.add(Component.literal(t.getInt("posX")+", "+t.getInt("posY")+", "+t.getInt("posZ")));}}}
}
